create table if not exists public.tickets (id text primary key, created_at timestamptz not null default now(), requester_name text not null, requester_email text not null, country text not null, study text not null, request_type text not null check (request_type in ('Muestra','Cotizaciones','Analisis','Otros')), detail text not null, status text not null default 'Pendiente' check (status in ('Pendiente','En proceso','Finalizado')), assignee text check (assignee in ('Diego','Miguel','Rony') or assignee is null), attachment_name text);
alter table public.tickets enable row level security;
create policy "Cualquiera puede crear solicitudes" on public.tickets for insert to anon,authenticated with check (true);
create policy "Solo analistas consultan" on public.tickets for select to authenticated using (auth.jwt()->>'email' in ('diego@dichter-neira.com','miguel@dichter-neira.com','rony@dichter-neira.com','dmontoya@dichter-neira.com'));
create policy "Solo analistas actualizan" on public.tickets for update to authenticated using (auth.jwt()->>'email' in ('diego@dichter-neira.com','miguel@dichter-neira.com','rony@dichter-neira.com','dmontoya@dichter-neira.com')) with check (auth.jwt()->>'email' in ('diego@dichter-neira.com','miguel@dichter-neira.com','rony@dichter-neira.com','dmontoya@dichter-neira.com'));
insert into storage.buckets (id,name,public) values ('ticket-files','ticket-files',false) on conflict do nothing;
create policy "Cualquiera carga adjuntos" on storage.objects for insert to anon,authenticated with check (bucket_id='ticket-files');
create policy "Analistas descargan adjuntos" on storage.objects for select to authenticated using (bucket_id='ticket-files' and auth.jwt()->>'email' in ('diego@dichter-neira.com','miguel@dichter-neira.com','rony@dichter-neira.com','dmontoya@dichter-neira.com'));
